import { resolvers } from '@hozu/data'
import { app } from '@hozu/runtime-server'
import project from './hozu.config.ts'
import { notesResolvers } from './features/notes/server.ts'
import { accountResolvers } from './features/account/server.ts'
import { createUndoStore } from './features/notes/undo.ts'
import { createUserDirectory } from './features/account/users.ts'
import { createNoteStore } from './features/notes/store.ts'

const undo = createUndoStore()
const users = createUserDirectory()
const notes = createNoteStore()

export default app({
  resolvers: resolvers(project, (implement) => [
    ...accountResolvers(implement, undo, users, notes),
    ...notesResolvers(implement, undo, users, notes),
  ]),
})
import { endpoint, event, fn, invoke, machine, mutation, on, query, tag } from '@hozu/core'
import { z } from 'zod'

export const Note = z.object({
  id: z.string(),
  title: z.string(),
  number: z.number().int(),
  pinned: z.boolean(),
  createdAt: z.string(),
  sharedWith: z.array(z.string()),
  body: z.string(),
})
export const SharedNote = z.object({ id: z.string(), title: z.string(), owner: z.string() })
export const NoteKey = z.object({ id: z.string() })
export const NewNote = z.object({
  title: z.string().trim().min(1, 'Write a note').max(60, 'Use at most 60 characters'),
})

export const Draft = event({ payload: z.object({ title: z.string() }) })
export const Add = event({ payload: z.object({ title: z.string() }) })
export const Remove = event({ payload: NoteKey })
export const Pin = event({ payload: NoteKey })
export const Search = event({ payload: z.object({ text: z.string() }) })
export const Edit = event({ payload: z.object({ id: z.string(), title: z.string() }) })
export const EditDraft = event({ payload: z.object({ title: z.string() }) })
export const Save = event({ payload: z.object({ id: z.string(), title: z.string() }) })
export const Cancel = event({ payload: z.object({}) })
export const Archive = event({ payload: NoteKey })
export const Restore = event({ payload: NoteKey })
export const Undo = event({ payload: z.object({}) })
export const Select = event({ payload: z.object({ id: z.string(), checked: z.boolean() }) })
export const Share = event({ payload: z.object({ id: z.string(), name: z.string() }) })
export const Unshare = event({ payload: z.object({ id: z.string(), name: z.string() }) })
export const SaveNote = event({ payload: z.object({ id: z.string(), title: z.string(), body: z.string() }) })
export const Bulk = event({ payload: z.object({ ids: z.array(z.string()), action: z.string().nullable() }) })

export const notesTag = tag({ param: null })

export const ExportedNote = z.object({
  title: z.string(),
  pinned: z.boolean(),
  archived: z.boolean(),
  createdAt: z.string(),
})

export const exportNotes = endpoint({
  method: 'GET',
  path: '/api/export',
  input: z.object({}),
  output: z.object({ user: z.string(), notes: z.array(ExportedNote) }),
  errors: { Unauthorized: z.object({ message: z.string() }) },
  failed: { Unauthorized: 401 },
})

const IsArchived = { Archived: NoteKey }

export const listNotes = query({
  input: z.object({}),
  output: z.array(Note),
  errors: { Unauthorized: z.object({}) },
  scope: 'user',
  freshness: 'request',
  tags: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

export const NoteDetail = Note.extend({ archived: z.boolean() })

// One of the signed-in user's own notes, by its number (as written in the URL).
export const getNote = query({
  input: z.object({ number: z.string() }),
  output: NoteDetail,
  errors: { NotFound: z.object({}) },
  scope: 'user',
  freshness: 'request',
  tags: () => [notesTag()],
  runs: 'server',
  access: 'signedIn',
})

export const addNote = mutation({
  input: NewNote,
  output: Note,
  errors: { Duplicate: z.object({ title: z.string() }), TooMany: z.object({}) },
  invalidates: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

export const removeNote = mutation({
  input: NoteKey,
  output: NoteKey,
  errors: { NotFound: NoteKey, ...IsArchived },
  invalidates: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

export const renameNote = mutation({
  input: NoteKey.extend(NewNote.shape),
  output: Note,
  errors: { Duplicate: z.object({ title: z.string() }), NotFound: NoteKey, ...IsArchived },
  invalidates: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

// Saves a note's title and body from its page; the resolver checks both fields together, so every message shows at once.
export const editNote = mutation({
  input: NoteKey.extend({ title: z.string(), body: z.string() }),
  output: Note,
  errors: { NotFound: NoteKey, ...IsArchived },
  invalidates: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

export const togglePin = mutation({
  input: NoteKey,
  output: Note,
  errors: { NotFound: NoteKey, ...IsArchived },
  invalidates: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

export const listArchived = query({
  input: z.object({}),
  output: z.array(Note),
  errors: { Unauthorized: z.object({}) },
  scope: 'user',
  freshness: 'request',
  tags: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

export const archiveNote = mutation({
  input: NoteKey,
  output: Note,
  errors: { NotFound: NoteKey, ...IsArchived },
  invalidates: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

export const restoreNote = mutation({
  input: NoteKey,
  output: Note,
  errors: { NotFound: NoteKey },
  invalidates: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

export const lastDeleted = query({
  input: z.object({}),
  output: z.object({ title: z.string() }).nullable(),
  errors: { Unauthorized: z.object({}) },
  scope: 'user',
  freshness: 'request',
  tags: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

export const undoDelete = mutation({
  input: z.object({}),
  output: Note,
  errors: { NothingToUndo: z.object({}) },
  invalidates: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

export const NoteKeys = z.object({ ids: z.array(z.string()).min(1, 'Select at least one note') })

export const removeNotes = mutation({
  input: NoteKeys,
  output: z.object({ ids: z.array(z.string()) }),
  errors: {},
  invalidates: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

export const archiveNotes = mutation({
  input: NoteKeys,
  output: z.object({ ids: z.array(z.string()) }),
  errors: {},
  invalidates: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

export const sharedNotes = query({
  input: z.object({}),
  output: z.array(SharedNote),
  errors: { Unauthorized: z.object({}) },
  scope: 'user',
  freshness: 'request',
  tags: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

export const UserNotes = z.object({ name: z.string(), notes: z.number().int() })

export const adminUsers = query({
  input: z.object({}),
  output: z.array(UserNotes),
  errors: { Unauthorized: z.object({}), NotAdmin: z.object({}) },
  scope: 'user',
  freshness: 'request',
  tags: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

export const shareNote = mutation({
  input: NoteKey.extend({ name: z.string().regex(/^\s*[A-Za-z]{2,20}\s*$/, 'Use 2–20 letters') }),
  output: Note,
  errors: { Self: z.object({}), NotFound: NoteKey, ...IsArchived },
  invalidates: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

export const unshareNote = mutation({
  input: NoteKey.extend({ name: z.string() }),
  output: Note,
  errors: { NotFound: NoteKey },
  invalidates: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

const matches = (item: { title: string }, text: string) =>
  item.title.toLowerCase().includes(text.trim().toLowerCase())

export const visibleNotes = fn({
  input: z.object({ items: z.array(Note), text: z.string() }),
  output: z.array(Note),
  impl: ({ items, text }) => items.filter((item) => matches(item, text)),
})

export const PAGE_SIZE = 5

const Selection = z.object({ items: z.array(Note), text: z.string(), limit: z.number() })

export const listedNotes = fn({
  input: Selection,
  output: z.array(Note),
  impl: ({ items, text, limit }) => items.filter((item) => matches(item, text)).slice(0, limit),
})

export const selectedCount = fn({
  input: Selection.omit({ limit: true }),
  output: z.number(),
  impl: ({ items, text }) => items.filter((item) => matches(item, text)).length,
})

export const hasMore = fn({
  input: Selection,
  output: z.boolean(),
  impl: ({ items, text, limit }) => items.filter((item) => matches(item, text)).length > limit,
})

export const addedOn = fn({
  input: z.object({ at: z.string() }),
  output: z.string(),
  impl: ({ at }) => at.slice(0, 10),
})

export const numberParam = fn({
  input: z.object({ number: z.number() }),
  output: z.object({ number: z.string() }),
  impl: ({ number }) => ({ number: String(number) }),
})

export const noMatch = fn({
  input: z.object({ items: z.array(Note), text: z.string() }),
  output: z.boolean(),
  impl: ({ items, text }) => !items.some((item) => matches(item, text)),
})

export const DUPLICATE = 'duplicate'
export const NOT_FOUND = 'notFound'
export const ARCHIVED = 'archived'
export const TOO_MANY = 'tooMany'
export const NOTHING_TO_UNDO = 'nothingToUndo'
export const SELF_SHARE = 'selfShare'

export const notesMachine = machine({
  context: z.object({
    draft: z.string(),
    error: z.string().nullable(),
    fields: z.object({ title: z.string().nullable() }),
    target: z.string(),
    shareName: z.string(),
    search: z.string(),
    editing: z.string(),
    editTitle: z.string(),
    editError: z.string().nullable(),
    selected: z.array(z.string()),
    busy: z.boolean(),
    // The form on a note's page: what was typed stays in the fields until a save goes through.
    noteTitle: z.string(),
    noteBody: z.string(),
    kept: z.boolean(),
    saved: z.boolean(),
    noteFields: z.object({ title: z.string().nullable(), body: z.string().nullable() }),
  }),
  initialContext: {
    draft: '',
    error: null,
    fields: { title: null },
    target: '',
    shareName: '',
    search: '',
    editing: '',
    editTitle: '',
    editError: null,
    selected: [],
    busy: false,
    noteTitle: '',
    noteBody: '',
    kept: false,
    saved: false,
    noteFields: { title: null, body: null },
  },
  initial: 'idle',
  states: ({ ctx }) => ({
    idle: {
      on: [
        on(Draft, { target: 'idle', assign: (e) => { ctx.draft = e.title } }),
        on(Add, {
          target: 'adding',
          assign: (e) => {
            ctx.draft = e.title
            ctx.error = null
            ctx.fields = { title: null }
          },
        }),
        on(Select, { target: 'idle', guard: (e) => e.checked === true, assign: (e) => { ctx.selected.push(e.id) } }),
        on(Select, { target: 'idle', assign: (e) => { ctx.selected = ctx.selected.filter((id) => id !== e.id) } }),
        on(Bulk, {
          target: 'removingMany',
          guard: (e) => e.action === 'delete' && e.ids.length > 0,
          assign: (e) => { ctx.selected = e.ids; ctx.busy = true; ctx.error = null },
        }),
        on(Bulk, {
          target: 'archivingMany',
          guard: (e) => e.action === 'archive' && e.ids.length > 0,
          assign: (e) => { ctx.selected = e.ids; ctx.busy = true; ctx.error = null },
        }),
        on(Remove, { target: 'removing', assign: (e) => { ctx.target = e.id; ctx.error = null; ctx.selected = ctx.selected.filter((id) => id !== e.id) } }),
        on(Restore, { target: 'restoring', assign: (e) => { ctx.target = e.id; ctx.error = null } }),
        on(Archive, { target: 'archiving', assign: (e) => { ctx.target = e.id; ctx.error = null; ctx.selected = ctx.selected.filter((id) => id !== e.id) } }),
        on(Undo, { target: 'undoing', assign: () => { ctx.error = null } }),
        on(Share, { target: 'sharing', assign: (e) => { ctx.target = e.id; ctx.shareName = e.name; ctx.error = null } }),
        on(Unshare, { target: 'unsharing', assign: (e) => { ctx.target = e.id; ctx.shareName = e.name; ctx.error = null } }),
        on(Pin, { target: 'pinning', assign: (e) => { ctx.target = e.id; ctx.error = null } }),
        on(Search, { target: 'idle', assign: (e) => { ctx.search = e.text } }),
        on(Edit, {
          target: 'idle',
          assign: (e) => {
            ctx.editing = e.id
            ctx.editTitle = e.title
            ctx.editError = null
            ctx.error = null
          },
        }),
        on(EditDraft, { target: 'idle', assign: (e) => { ctx.editTitle = e.title } }),
        on(Cancel, { target: 'idle', assign: () => { ctx.editing = ''; ctx.editTitle = ''; ctx.editError = null; ctx.error = null } }),
        on(Save, {
          target: 'saving',
          assign: (e) => {
            ctx.editing = e.id
            ctx.editTitle = e.title
            ctx.editError = null
            ctx.error = null
          },
        }),
        on(SaveNote, {
          target: 'savingNote',
          assign: (e) => {
            ctx.target = e.id
            ctx.noteTitle = e.title
            ctx.noteBody = e.body
            ctx.saved = false
            ctx.noteFields = { title: null, body: null }
            ctx.error = null
          },
        }),
      ],
    },
    savingNote: {
      invoke: invoke(editNote, {
        input: { id: ctx.target, title: ctx.noteTitle, body: ctx.noteBody },
        done: { target: 'idle', assign: () => { ctx.kept = false; ctx.saved = true; ctx.noteTitle = ''; ctx.noteBody = '' } },
        failed: {
          Invalid: { target: 'idle', assign: (e) => { ctx.kept = true; ctx.noteFields = { title: e.fields.title, body: e.fields.body } } },
          NotFound: { target: 'idle', assign: () => { ctx.error = NOT_FOUND } },
          Archived: { target: 'idle', assign: () => { ctx.error = ARCHIVED } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.kept = true; ctx.error = e.message } },
        },
      }),
    },
    saving: {
      invoke: invoke(renameNote, {
        input: { id: ctx.editing, title: ctx.editTitle },
        done: { target: 'idle', assign: () => { ctx.editing = ''; ctx.editTitle = '' } },
        failed: {
          Duplicate: { target: 'idle', assign: () => { ctx.error = DUPLICATE } },
          Invalid: { target: 'idle', assign: (e) => { ctx.editError = e.fields.title } },
          NotFound: { target: 'idle', assign: () => { ctx.error = NOT_FOUND; ctx.editing = '' } },
          Archived: { target: 'idle', assign: () => { ctx.error = ARCHIVED; ctx.editing = '' } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    adding: {
      invoke: invoke(addNote, {
        input: { title: ctx.draft },
        done: { target: 'idle', assign: () => { ctx.draft = '' } },
        failed: {
          Duplicate: { target: 'idle', assign: () => { ctx.error = DUPLICATE } },
          TooMany: { target: 'idle', assign: () => { ctx.error = TOO_MANY } },
          Invalid: { target: 'idle', assign: (e) => { ctx.fields = e.fields } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    removing: {
      invoke: invoke(removeNote, {
        input: { id: ctx.target },
        done: 'idle',
        failed: {
          NotFound: { target: 'idle', assign: () => { ctx.error = NOT_FOUND } },
          Archived: { target: 'idle', assign: () => { ctx.error = ARCHIVED } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    removingMany: {
      invoke: invoke(removeNotes, {
        input: { ids: ctx.selected },
        done: { target: 'idle', assign: () => { ctx.selected = []; ctx.busy = false } },
        failed: {
          Invalid: { target: 'idle', assign: () => { ctx.selected = []; ctx.busy = false } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message; ctx.busy = false } },
        },
      }),
    },
    archivingMany: {
      invoke: invoke(archiveNotes, {
        input: { ids: ctx.selected },
        done: { target: 'idle', assign: () => { ctx.selected = []; ctx.busy = false } },
        failed: {
          Invalid: { target: 'idle', assign: () => { ctx.selected = []; ctx.busy = false } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message; ctx.busy = false } },
        },
      }),
    },
    pinning: {
      invoke: invoke(togglePin, {
        input: { id: ctx.target },
        done: 'idle',
        failed: {
          NotFound: { target: 'idle', assign: () => { ctx.error = NOT_FOUND } },
          Archived: { target: 'idle', assign: () => { ctx.error = ARCHIVED } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    sharing: {
      invoke: invoke(shareNote, {
        input: { id: ctx.target, name: ctx.shareName },
        done: { target: 'idle', assign: () => { ctx.shareName = '' } },
        failed: {
          Self: { target: 'idle', assign: () => { ctx.error = SELF_SHARE } },
          Invalid: { target: 'idle', assign: (e) => { ctx.error = e.fields.name } },
          NotFound: { target: 'idle', assign: () => { ctx.error = NOT_FOUND } },
          Archived: { target: 'idle', assign: () => { ctx.error = ARCHIVED } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    unsharing: {
      invoke: invoke(unshareNote, {
        input: { id: ctx.target, name: ctx.shareName },
        done: { target: 'idle', assign: () => { ctx.shareName = '' } },
        failed: {
          NotFound: { target: 'idle', assign: () => { ctx.error = NOT_FOUND } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    archiving: {
      invoke: invoke(archiveNote, {
        input: { id: ctx.target },
        done: 'idle',
        failed: {
          NotFound: { target: 'idle', assign: () => { ctx.error = NOT_FOUND } },
          Archived: { target: 'idle', assign: () => { ctx.error = ARCHIVED } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    undoing: {
      invoke: invoke(undoDelete, {
        input: {},
        done: 'idle',
        failed: {
          NothingToUndo: { target: 'idle', assign: () => { ctx.error = NOTHING_TO_UNDO } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    restoring: {
      invoke: invoke(restoreNote, {
        input: { id: ctx.target },
        done: 'idle',
        failed: {
          NotFound: { target: 'idle', assign: () => { ctx.error = NOT_FOUND } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
  }),
})
import type { Implement } from '@hozu/data'
import { adminUsers, addNote, getNote, exportNotes, archiveNote, archiveNotes, removeNotes, lastDeleted, listArchived, listNotes, removeNote, renameNote, editNote, restoreNote, shareNote, sharedNotes, togglePin, undoDelete, unshareNote } from './model.ts'
import { type Item, type UndoStore, undoKeyOf } from './undo.ts'
import { type UserDirectory, isAdmin } from '../account/users.ts'
import { type NoteStore, nextNumber } from './store.ts'

const view = ({ archived: _, ...item }: Item) => ({ ...item, sharedWith: [...item.sharedWith] })

export function notesResolvers<Env>(implement: Implement<{ user: string }, Env>, undo: UndoStore, users: UserDirectory, notes: NoteStore) {
  const { notes: store, owners, added } = notes
  const keyOf = (session: { user: string }) => session.user.toLowerCase()
  const listOf = (session: { user: string } | null): Item[] => (session ? (store.get(keyOf(session)) ?? []) : [])
  const ownListOf = (session: { user: string } | null) => {
    if (!session) return []
    const list = store.get(keyOf(session)) ?? []
    store.set(keyOf(session), list)
    return list
  }
  // Times of the adds that went through, per user: at most ADD_LIMIT within ADD_WINDOW_MS.
  const ADD_LIMIT = 10
  const ADD_WINDOW_MS = 60_000
  const recentAdds = (session: { user: string }, now: number) => {
    const times = (added.get(keyOf(session)) ?? []).filter((at) => now - at < ADD_WINDOW_MS)
    added.set(keyOf(session), times)
    return times
  }
  const forget = (session: { user: string } | null) => {
    if (session) undo.delete(undoKeyOf(session))
  }
  return [
    implement(adminUsers, (_, { session, fail }) => {
      if (!session) return fail('Unauthorized', {})
      if (!isAdmin(session)) return fail('NotAdmin', {})
      const keys = new Set([...users.keys(), ...[...store].filter(([, items]) => items.length > 0).map(([key]) => key)])
      return [...keys]
        .map((key) => ({ name: users.get(key) ?? owners.get(key) ?? key, notes: store.get(key)?.length ?? 0 }))
        .sort((a, b) => a.name.toLowerCase().localeCompare(b.name.toLowerCase()))
    }),
    implement(listNotes, (_, { session, fail }) =>
      session
        ? [...listOf(session).filter((item) => !item.archived && item.pinned), ...listOf(session).filter((item) => !item.archived && !item.pinned)].map(view)
        : fail('Unauthorized', {}),
    ),
    implement(getNote, ({ number }, { session, fail }) => {
      if (!session) return fail('NotFound', {})
      const item = /^[1-9][0-9]*$/.test(number) ? listOf(session).find((entry) => entry.number === Number(number)) : undefined
      if (!item) return fail('NotFound', {})
      return { ...view(item), archived: item.archived }
    }),
    implement(exportNotes, (_, { session, fail }) => {
      if (!session) return fail('Unauthorized', { message: 'Sign in' })
      const own = listOf(session)
      return {
        user: session.user,
        notes: [...own.filter((item) => item.pinned), ...own.filter((item) => !item.pinned)].map((item) => ({
          title: item.title,
          pinned: item.pinned,
          archived: item.archived,
          createdAt: new Date(item.createdAt).toISOString(),
        })),
      }
    }),
    implement(listArchived, (_, { session, fail }) =>
      session
        ? listOf(session).filter((item) => item.archived).sort((a, b) => b.createdAt.localeCompare(a.createdAt)).map(view)
        : fail('Unauthorized', {}),
    ),
    implement(sharedNotes, (_, { session, fail }) => {
      if (!session) return fail('Unauthorized', {})
      const me = keyOf(session)
      return [...store].flatMap(([owner, items]) =>
        owner === me
          ? []
          : items
              .filter((item) => !item.archived && item.sharedWith.some((name) => name.toLowerCase() === me))
              .map((item) => ({ id: item.id, title: item.title, owner: owners.get(owner) ?? owner })),
      )
    }),
    implement(shareNote, ({ id, name }, { fail, session }) => {
      const item = listOf(session).find((entry) => entry.id === id)
      if (!session || !item) return fail('NotFound', { id })
      if (item.archived) return fail('Archived', { id })
      const clean = name.trim()
