import type { Item } from './undo.ts'

// Every user's notes, by lower-cased name, with who shared them and when they added them.
export type NoteStore = {
  notes: Map<string, Item[]>
  // Display name of each owner who has shared a note, by store key.
  owners: Map<string, string>
  // Times of the adds that went through, per user.
  added: Map<string, number[]>
  // Highest note number each user has ever had; numbers are never reused.
  numbers: Map<string, number>
  nextId: () => string
}

export function createNoteStore(): NoteStore {
  let seq = 0
  const nextId = () => `n${++seq}`
  const seed = (notes: [string, string][]) => notes.map(([title, createdAt]) => ({ id: nextId(), title, number: 0, pinned: false, createdAt, archived: false, sharedWith: [] as string[], body: '' }))
  const notes = new Map<string, Item[]>([
    ['ada', seed([['Buy milk', '2026-01-15T09:00:00.000Z'], ['Call Bob', '2026-01-14T09:00:00.000Z']])],
    ['bob', seed([["Bob's secret", '2026-01-10T09:00:00.000Z']])],
  ])
  // Existing notes are numbered by when they were added, oldest first.
  const numbers = new Map<string, number>()
  for (const [key, items] of notes) {
    const oldestFirst = [...items].sort((a, b) => a.createdAt.localeCompare(b.createdAt))
    oldestFirst.forEach((item, index) => (item.number = index + 1))
    numbers.set(key, oldestFirst.length)
  }
  return {
    notes,
    owners: new Map(),
    added: new Map(),
    numbers,
    nextId,
  }
}

// Drops everything kept for a user: their notes (archived and shared ones included), sharing, add history and numbering.
export const purgeUser = (store: NoteStore, key: string) => {
  store.notes.delete(key)
  store.owners.delete(key)
  store.added.delete(key)
  store.numbers.delete(key)
}

// The next number for a user's new note: one past the highest they have ever had.
export const nextNumber = (store: NoteStore, key: string) => {
  const number = (store.numbers.get(key) ?? 0) + 1
  store.numbers.set(key, number)
  return number
}
export type Item = { id: string; title: string; number: number; pinned: boolean; createdAt: string; archived: boolean; sharedWith: string[]; body: string }

// The most recent delete per user, kept until it is undone, the user's notes change again or the user signs out.
export type UndoStore = Map<string, { item: Item; at: number }>

export const createUndoStore = (): UndoStore => new Map()

export const undoKeyOf = (session: { user: string }) => session.user.toLowerCase()
import { feature } from '@hozu/core'
import * as model from './model.ts'
import * as views from './views.ts'
import * as text from './text.ts'

export const account = feature({
  id: 'account',
  intent: { summary: 'Sign in with a name, sign out; the session identifies the user' },
  exports: [model.me],
  declarations: [model, views, text],
})
import { endpoint, event, invoke, machine, mutation, on, query, ui } from '@hozu/core'
import { z } from 'zod'
import { home, login } from '../../routes.ts'

export const Session = z.object({ user: z.string() })
export const Name = z.object({ name: z.string().regex(/^\s*[A-Za-z]{2,20}\s*$/, 'Use 2–20 letters') })

export const SignIn = event({ payload: z.object({ name: z.string() }) })
export const SignOut = event({ payload: z.object({}) })
export const DeleteAccount = event({ payload: z.object({}) })

export const me = query({
  input: z.object({}),
  output: z.object({ name: z.string(), admin: z.boolean() }),
  errors: { Unauthorized: z.object({}) },
  scope: 'user',
  freshness: 'request',
  runs: 'server',
  access: 'anyone',
})

export const signIn = mutation({ input: Name, output: z.object({}), runs: 'server', access: 'anyone' })
export const signOut = mutation({ input: z.object({}), output: z.object({}), runs: 'server', access: 'anyone' })
export const removeAccount = mutation({ input: z.object({}), output: z.object({}), runs: 'server', access: 'anyone' })

export const root = endpoint({ method: 'GET', path: '/', input: z.object({}), output: 'redirect' })

export const accountMachine = machine({
  context: z.object({
    draft: z.string(),
    error: z.string().nullable(),
    fields: z.object({ name: z.string().nullable() }),
  }),
  initialContext: { draft: '', error: null, fields: { name: null } },
  initial: 'idle',
  states: ({ ctx }) => ({
    idle: {
      on: [
        on(SignIn, {
          target: 'signingIn',
          assign: (e) => { ctx.draft = e.name; ctx.error = null; ctx.fields = { name: null } },
        }),
        on(SignOut, { target: 'signingOut' }),
        on(DeleteAccount, { target: 'deletingAccount', assign: () => { ctx.error = null } }),
      ],
    },
    signingIn: {
      invoke: invoke(signIn, {
        input: { name: ctx.draft },
        done: { target: 'idle', navigate: () => ui.link(home, null) },
        failed: {
          Invalid: { target: 'idle', assign: (e) => { ctx.fields = e.fields } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    signingOut: {
      invoke: invoke(signOut, {
        input: {},
        done: { target: 'idle', navigate: () => ui.link(login, null) },
        failed: { Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } } },
      }),
    },
    deletingAccount: {
      invoke: invoke(removeAccount, {
        input: {},
        done: { target: 'idle', navigate: () => ui.link(login, null, { deleted: true }) },
        failed: { Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } } },
      }),
    },
  }),
})
import type { Implement } from '@hozu/data'
import { ui } from '@hozu/core'
import { home, login } from '../../routes.ts'
import { me, removeAccount, root, signIn, signOut } from './model.ts'
import { type UndoStore, undoKeyOf } from '../notes/undo.ts'
import { type UserDirectory, isAdmin } from './users.ts'
import { type NoteStore, purgeUser } from '../notes/store.ts'

export function accountResolvers<Env>(implement: Implement<{ user: string }, Env>, undo: UndoStore, users: UserDirectory, notes: NoteStore) {
  return [
    implement(me, (_, { session, fail }) => (session ? { name: session.user, admin: isAdmin(session) } : fail('Unauthorized', {}))),
    implement(root, (_, { session, redirect }) => redirect(session ? ui.link(home, null) : ui.link(login, null))),
    implement(signIn, ({ name }, { setSession }) => {
      setSession({ user: name.trim() })
      users.set(name.trim().toLowerCase(), name.trim())
      return {}
    }),
    implement(signOut, (_, { session, setSession }) => {
      if (session) undo.delete(undoKeyOf(session))
      setSession(null)
      return {}
    }),
    implement(removeAccount, (_, { session, setSession }) => {
      if (session) {
        const key = session.user.trim().toLowerCase()
        purgeUser(notes, key)
        users.delete(key)
        undo.delete(undoKeyOf(session))
      }
      setSession(null)
      return {}
    }),
  ]
}
import { ui } from '@hozu/core'

export const text = ui.messages('en', {
